// Command tlssrv is the host-side acceptance peer for the esp-emu TLS
// probes (_demo/esp-idf-wifi): a TLS echo server on 127.0.0.1:9443 built on
// crypto/tls only (no external dependencies). The emulator's user-mode NAT
// aliases its gateway address (192.168.4.1 in the default subnet) to the
// host and forwards guest connections to the same port on the host's
// loopback, so the firmware's TLSDial(192.168.4.1, 9443, ...) lands here.
//
// The certificate and key come from the certs/ directory next to this file,
// generated by idfproj/host/gencert.sh (gitignored - private key material
// never enters version control). The script also writes the CA PEM into
// idfproj/main/tls_ca.h, which compiles it into the firmware for the
// VERIFY_REQUIRED dial.
//
// Usage:
//
//	go run ./idfproj/host/tlssrv [listen-addr]   (default 127.0.0.1:9443)
//
// Every connection is logged: the negotiated TLS version and cipher suite,
// the echoed byte count, and how the peer ended the session. A graceful
// end (the firmware's close_notify) surfaces as io.EOF on the drained
// read; an abrupt TCP disconnect surfaces as a connection-reset error - the
// log line is the host-side evidence for the close_notify round trip.
package main

import (
	"crypto/tls"
	"io"
	"log"
	"os"
	"path/filepath"
	"runtime"
	"time"
)

func main() {
	addr := "127.0.0.1:9443"
	if len(os.Args) > 1 {
		addr = os.Args[1]
	}
	_, thisFile, _, _ := runtime.Caller(0)
	certFile := filepath.Join(filepath.Dir(thisFile), "certs", "tls.crt")
	keyFile := filepath.Join(filepath.Dir(thisFile), "certs", "tls.key")
	cert, err := tls.LoadX509KeyPair(certFile, keyFile)
	if err != nil {
		log.Fatalf("tlssrv: load certificate: %v (run idfproj/host/gencert.sh first)", err)
	}
	cfg := &tls.Config{
		Certificates: []tls.Certificate{cert},
		MinVersion:   tls.VersionTLS12,
	}
	ln, err := tls.Listen("tcp", addr, cfg)
	if err != nil {
		log.Fatalf("tlssrv: listen %s: %v", addr, err)
	}
	log.Printf("tlssrv: listening on %s (TLS >= 1.2)", ln.Addr())
	for {
		conn, err := ln.Accept()
		if err != nil {
			log.Fatalf("tlssrv: accept: %v", err)
		}
		go echo(conn.(*tls.Conn))
	}
}

// echo reads the whole session and writes every byte back until the peer
// closes; each connection is bounded by a 30s deadline so a stuck firmware
// probe cannot leak one. The trailing read that reports how the session
// ended is the close_notify evidence: io.EOF there means the peer sent the
// TLS close notification before dropping the connection.
func echo(conn *tls.Conn) {
	defer conn.Close()
	remote := conn.RemoteAddr()
	if err := conn.SetDeadline(time.Now().Add(30 * time.Second)); err != nil {
		log.Printf("tlssrv: set deadline: %v", err)
		return
	}
	n, err := io.Copy(conn, conn)
	// Read the negotiated parameters after the echo: ConnectionState before
	// the first read would return zeros (the server handshake is lazy).
	state := conn.ConnectionState()
	how := "unexpected data or error"
	_, rerr := conn.Read(make([]byte, 1))
	switch {
	case rerr == io.EOF:
		how = "peer sent TLS close_notify"
	case rerr == nil:
		how = "peer still sending"
	}
	log.Printf("tlssrv: connection from %s: %s %s, echoed %d bytes (copy err=%v), %s",
		remote, tlsVersion(state.Version), cipherSuite(state.CipherSuite), n, err, how)
	if rerr != nil && rerr != io.EOF {
		log.Printf("tlssrv: trailing read: %v", rerr)
	}
}

// tlsVersion names a TLS version constant; unknown values print as hex.
func tlsVersion(v uint16) string {
	switch v {
	case tls.VersionTLS10:
		return "TLS1.0"
	case tls.VersionTLS11:
		return "TLS1.1"
	case tls.VersionTLS12:
		return "TLS1.2"
	case tls.VersionTLS13:
		return "TLS1.3"
	}
	return "TLS?"
}

// cipherSuite names the negotiated suite for the log; unknown values print
// as hex. Only the suites this probe's run actually negotiates are named.
func cipherSuite(id uint16) string {
	names := map[uint16]string{
		tls.TLS_AES_128_GCM_SHA256:                  "TLS_AES_128_GCM_SHA256",
		tls.TLS_AES_256_GCM_SHA384:                  "TLS_AES_256_GCM_SHA384",
		tls.TLS_CHACHA20_POLY1305_SHA256:            "TLS_CHACHA20_POLY1305_SHA256",
		tls.TLS_ECDHE_RSA_WITH_AES_128_GCM_SHA256:   "TLS_ECDHE_RSA_WITH_AES_128_GCM_SHA256",
		tls.TLS_ECDHE_RSA_WITH_AES_256_GCM_SHA384:   "TLS_ECDHE_RSA_WITH_AES_256_GCM_SHA384",
		tls.TLS_ECDHE_ECDSA_WITH_AES_128_GCM_SHA256: "TLS_ECDHE_ECDSA_WITH_AES_128_GCM_SHA256",
		tls.TLS_ECDHE_RSA_WITH_CHACHA20_POLY1305:    "TLS_ECDHE_RSA_WITH_CHACHA20_POLY1305",
	}
	if name, ok := names[id]; ok {
		return name
	}
	return "suite 0x" + hex16(id)
}

func hex16(v uint16) string {
	const digits = "0123456789abcdef"
	return string([]byte{digits[v>>12&15], digits[v>>8&15], digits[v>>4&15], digits[v&15]})
}
